        pt.0.addr() != MAP_FAILED ==> pt.0.addr() + len < usize::MAX,
        pt.0.addr() != MAP_FAILED ==> pt.0 as int % page_size() == 0,
        pt.0.addr() != MAP_FAILED ==> pt.0@.provenance == pt.1@.points_to.provenance(),
{
