        }
    }

    #[inline(always)]
    pub fn take(&self) -> (ll: LL)
        requires self.wf()
        ensures
            ll.wf(),
            ll.instance() == self.instance,
            ll.heap_id() == Some(self.heap_id@),
    {
        let res = self.atomic.load();
        if res.addr() == 0 {
